Q: How to center selected text in PDFView? A: <p>You were kind of on the right track with the offset, but <code>page.bounds(for: .bleedBox).height / 2.0</code> is half of the PDF's page itself, it's not half of the visible screen. In other words that value uses page coordinates, not viewport coordinates. That's probably why you got the wrong offset. Instead you could just use the <code>UIScrollView</code> directly to get the center relative to what the user can actually see</p>
<h2>Current solution</h2>
<p>First get the scroll view:</p>
<pre><code>extension UIView {
    var pdfScrollView: UIScrollView? {
        if let scrollView = self as? UIScrollView { return scrollView }
        for subview in subviews {
            if let scrollView = subview.pdfScrollView { return scrollView }
        }
        return nil
    }
}
</code></pre>
<p>Then for the button:</p>
<pre><code>Button(&quot;Center Selection&quot;) {
    guard let pdfView = self.pdfView,
          let selection = pdfView.currentSelection,
          let page = selection.pages.first,
          let scrollView = pdfView.pdfScrollView else { return }

    let bounds = selection.bounds(for: page)


    let selectionInView = pdfView.convert(bounds, from: page)
    let targetOffsetY = scrollView.contentOffset.y + (selectionInView.midY - pdfView.bounds.midY)
    let maxOffsetY = max(0, scrollView.contentSize.height - scrollView.bounds.height)
    let clampedOffsetY = max(0, min(targetOffsetY, maxOffsetY))

    scrollView.setContentOffset(CGPoint(x: scrollView.contentOffset.x, y: clampedOffsetY), animated: true)
}
</code></pre>
<h2>Old solution</h2>
<p>My old solution used the <code>PDFDestination</code> approach to find the center but that had mixed results around pages edges and boundaries. The GIF below is of the old solution:</p>
<pre class="lang-swift prettyprint-override"><code>
Button(&quot;Center Selection&quot;)
{
    if let pdfView = self.pdfView,
       let selection = pdfView.currentSelection,
       let page = selection.pages.first
    {
        let bounds = selection.bounds(for: page)


        let topLeftPage = pdfView.convert(CGPoint(x: 0, y: 0), to: page)
        let centerPage = pdfView.convert(CGPoint(x: pdfView.bounds.midX, y: pdfView.bounds.midY), to: page)

        // offsetX is technically not needed, unless your user is going to zoom in or horizontally scroll the PDF
        let offsetX = topLeftPage.x - centerPage.x
        let offsetY = topLeftPage.y - centerPage.y


        let destinationPoint = CGPoint(
            x: bounds.midX + offsetX,
            y: bounds.midY + offsetY
        )

        let destination = PDFDestination(page: page, at: destinationPoint)

        UIView.animate(withDuration: 0.3)
        {
            pdfView.go(to: destination)
        }
    }
}
</code></pre>
